INSERT INTO `li_member_benefit` VALUES (4, NULL, '2026-11-04 16:29:19.000000', b'0', 'admin', '2026-11-04 21:38:51.189000', '购物1.5倍积分', 'https://lilishop-oss.oss-cn-beijing.aliyuncs.com/MANAGER/2117947015370043393/58e629e0915e481181ca574371688759.png', 'POINT_MULTIPLIER', '<p>订单完成后按购物积分规则获得1.5倍积分&#xff1b;同类倍率取最高值。</p>', 4, 'OPEN', '{\"multiplier\":1.5}');
INSERT INTO `li_member_benefit` VALUES (5, NULL, '2026-11-04 16:29:19.000000', b'0', 'admin', '2026-11-04 21:39:02.141000', '购物双倍积分', 'https://lilishop-oss.oss-cn-beijing.aliyuncs.com/MANAGER/2117947015370043393/35b640facdc543db9b57a2b47643816a.png', 'POINT_MULTIPLIER', '<p>订单完成后按购物积分规则获得2倍积分&#xff1b;退款按下单规则回退。</p>', 5, 'OPEN', '{\"multiplier\":2}');
