INSERT INTO `li_setting` VALUES ('TIMED_TASK_SETTING', 'SYSTEM', '2026-10-29 16:49:01.023000', b'0', 'admin', '2026-10-29 17:00:00.054000', '[{\"id\":\"ORDER_AUTO_COMPLETE\",\"name\":\"订单自动确认收货\",\"description\":\"订单发货后达到自动收货时限自动确认收货\",\"group\":\"订单任务\",\"cron\":\"0 0 3 * * ?\",\"status\":true,\"lastExecTime\":1793264198281,\"lastExecStatus\":1,\"lastExecCost\":778},{\"id\":\"ORDER_AUTO_EVALUATE\",\"name\":\"订单自动好评\",\"description\":\"订单完成达到评价时限未评价自动五星好评\",\"group\":\"订单任务\",\"cron\":\"0 0 3 * * ?\",\"status\":true},{\"id\":\"ORDER_CLOSE_AFTER_SALE\",\"name\":\"自动关闭超时售后\",\"description\":\"买家申请售后超时未处理或未退货自动关闭\",\"group\":\"订单任务\",\"cron\":\"0 0 4 * * ?\",\"status\":true},{\"id\":\"ORDER_CLOSE_COMPLAINT\",\"name\":\"自动关闭超时投诉\",\"description\":\"交易投诉超时未响应自动关闭\",\"group\":\"订单任务\",\"cron\":\"0 0 4 * * ?\",\"status\":true},{\"id\":\"ORDER_PROFIT_SHARING\",\"name\":\"订单分账与解冻\",\"description\":\"订单结算周期完成后解冻佣金与分账\",\"group\":\"订单任务\",\"cron\":\"0 0 5 * * ?\",\"status\":true},{\"id\":\"ORDER_CREATE_BILL\",\"name\":\"生成店铺结算单\",\"description\":\"按店铺结算周期生成每日或每月对账结算单\",\"group\":\"订单任务\",\"cron\":\"0 0 6 * * ?\",\"status\":true},{\"id\":\"CancelOrderTaskExecute\",\"name\":\"订单超时自动取消\",\"description\":\"未付款订单超时后自动取消并释放库存\",\"group\":\"订单任务\",\"cron\":\"0 0/5 * * ?\",\"status\":true},{\"id\":\"RechargeOrderTaskExecute\",\"name\":\"充值订单超时取消\",\"description\":\"充值未付款订单超时后关闭\",\"group\":\"订单任务\",\"cron\":\"0 0/10 * * ?\",\"status\":true},{\"id\":\"AppointmentMinuteTaskExecute\",\"name\":\"预约订单超时核销与提醒\",\"description\":\"预约服务未到店核销自动处理及临期服务微信提醒\",\"group\":\"预约任务\",\"cron\":\"0 0/5 * * ?\",\"status\":true},{\"id\":\"CouponExecute\",\"name\":\"优惠券状态更新\",\"description\":\"失效或过期优惠券自动标记为已过期\",\"group\":\"营销任务\",\"cron\":\"0 0/30 * * ?\",\"status\":true},{\"id\":\"GiftCardCashExpireExecute\",\"name\":\"礼品卡现金过期处理\",\"description\":\"礼品卡绑定的余额过期处理\",\"group\":\"营销任务\",\"cron\":\"0 0 0 * * ?\",\"status\":true},{\"id\":\"PromotionEverydayExecute\",\"name\":\"促销活动每日更新\",\"description\":\"每日秒杀、拼团、满减等活动的开始与结束状态流转\",\"group\":\"营销任务\",\"cron\":\"0 0 0 * * ?\",\"status\":true},{\"id\":\"MemberCouponSignEverydayExecute\",\"name\":\"会员优惠券每日签到\",\"description\":\"会员每日签到领券等定时触发\",\"group\":\"营销任务\",\"cron\":\"0 0 0 * * ?\",\"status\":true},{\"id\":\"GoodsExecute\",\"name\":\"商品定时上下架\",\"description\":\"定时上架或达到下架时间的商品状态流转\",\"group\":\"商品任务\",\"cron\":\"0 0/10 * * ?\",\"status\":true},{\"id\":\"HotWordsEveryDayTaskExecute\",\"name\":\"搜索热词每日更新\",\"description\":\"统计搜索频次更新热门搜索关键词\",\"group\":\"商品任务\",\"cron\":\"0 0 1 * * ?\",\"status\":true},{\"id\":\"StoreExecute\",\"name\":\"店铺状态处理\",\"description\":\"店铺过期或年费到期状态处理\",\"group\":\"店铺任务\",\"cron\":\"0 0/30 * * ?\",\"status\":true},{\"id\":\"StoreRatingExecute\",\"name\":\"店铺评分统计更新\",\"description\":\"根据近期用户评价重新计算店铺综合评分\",\"group\":\"店铺任务\",\"cron\":\"0 0 2 * * ?\",\"status\":true},{\"id\":\"BroadcastExecute\",\"name\":\"小程序直播状态同步\",\"description\":\"同步微信小程序直播间数据和回放状态\",\"group\":\"系统任务\",\"cron\":\"0 0/30 * * ?\",\"status\":true},{\"id\":\"DistributionRelationExpireExecute\",\"name\":\"分销绑定关系过期\",\"description\":\"超过有效期的分销关系自动解绑\",\"group\":\"分销任务\",\"cron\":\"0 0 2 * * ?\",\"status\":true},{\"id\":\"OnlineMemberStatistics\",\"name\":\"在线会员统计\",\"description\":\"统计当前在线用户数与会话情况\",\"group\":\"统计任务\",\"cron\":\"0 0/10 * * ?\",\"status\":true},{\"id\":\"PageViewStatisticsExecute\",\"name\":\"页面访问PV/UV统计\",\"description\":\"按小时归档店铺与平台页面访问量\",\"group\":\"统计任务\",\"cron\":\"0 0 * * * ?\",\"status\":true,\"lastExecTime\":1793264400033,\"lastExecStatus\":1,\"lastExecCost\":33},{\"id\":\"MemberStatisticsExecute\",\"name\":\"会员活跃与增长统计\",\"description\":\"每日归档会员总数、新增会员与活跃情况\",\"group\":\"统计任务\",\"cron\":\"0 0 1 * * ?\",\"status\":true}]');
