  `refund_time` datetime(6) NULL DEFAULT NULL COMMENT '退款时间',
  `refund_way` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '退款方式',
