DROP TABLE IF EXISTS `li_card_key`;
CREATE TABLE `li_card_key`  (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` bit(1) NULL DEFAULT b'0' COMMENT '删除标志 false/true',
  `sku_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'SKU ID',
  `goods_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品 SPU ID',
  `store_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '店铺 ID',
  `card_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '卡号',
  `card_secret` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '卡密(明文)',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'UNUSED' COMMENT 'UNUSED/RESERVED/ALLOCATED/VOIDED',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '绑定订单号（RESERVED/ALLOCATED 时写入）',
  `order_item_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '绑定订单项号（RESERVED/ALLOCATED 时写入）',
  `member_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '买家 ID（RESERVED/ALLOCATED 时写入）',
  `allocated_time` datetime NULL DEFAULT NULL COMMENT '发卡时间（仅 ALLOCATED 时写入；RESERVED 预占时为 NULL）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sku_card_no`(`sku_id` ASC, `card_no` ASC) USING BTREE,
  INDEX `idx_sku_status`(`sku_id` ASC, `status` ASC, `delete_flag` ASC) USING BTREE,
  INDEX `idx_store_sku`(`store_id` ASC, `sku_id` ASC) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_order_item_sn`(`order_item_sn` ASC) USING BTREE,
  INDEX `idx_order_status`(`order_sn` ASC, `status` ASC, `delete_flag` ASC) USING BTREE,
  INDEX `idx_member_id`(`member_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '电子卡券卡密池' ROW_FORMAT = DYNAMIC;

