  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '更新时间',
  `end_time` datetime(6) NULL DEFAULT NULL COMMENT '活动结束时间',
  `promotion_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '活动名称',
  `store_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '店铺ID',
  `store_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '店铺名称',
  `start_time` datetime(6) NULL DEFAULT NULL COMMENT '活动开始时间',
  `consume_threshold` decimal(10, 2) NULL DEFAULT NULL COMMENT '消费门槛',
  `coupon_discount` decimal(10, 2) NULL DEFAULT NULL COMMENT '折扣',
  `coupon_limit_num` int NULL DEFAULT NULL COMMENT '领取限制',
  `coupon_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '优惠券名称',
  `coupon_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '活动类型',
  `description` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '活动描述',
  `get_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '优惠券类型',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '面额',
  `publish_num` int NULL DEFAULT NULL COMMENT '发行数量',
  `received_num` int NULL DEFAULT NULL COMMENT '已被领取的数量',
  `scope_id` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '范围关联的ID',
  `scope_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '关联范围类型',
  `store_commission` decimal(10, 2) NULL DEFAULT NULL COMMENT '店铺承担比例',
  `used_num` int NULL DEFAULT NULL COMMENT '已被使用的数量',
  `range_day_type` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `effective_days` int NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '优惠券' ROW_FORMAT = DYNAMIC;

