  INDEX `idx_li_damage_report_store_id`(`store_id` ASC) USING BTREE,
  INDEX `idx_li_damage_report_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '报损单' ROW_FORMAT = DYNAMIC;

