-- ----------------------------
-- Table structure for li_distribution
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution`;
CREATE TABLE `li_distribution`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `create_by` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '创建时间',
  `delete_flag` bit(1) NULL DEFAULT NULL COMMENT '删除标志 true/false 删除/未删除',
  `update_by` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '更新时间',
  `can_rebate` decimal(10, 2) NULL DEFAULT NULL COMMENT '可提现金额',
  `commission_frozen` decimal(10, 2) NULL DEFAULT NULL COMMENT '冻结金额',
  `distribution_status` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '分销商状态',
  `grade_id` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '当前分销等级值（1-5）',
  `parent_distribution_id` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '上级分销员ID',
  `invite_code` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '分销员邀请码（全局唯一）',
  `join_time` datetime NULL DEFAULT NULL COMMENT '正式加入分销时间（审核通过时间）',
  `valid_sales_amount` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '累计有效销售额（等级升级口径，退款冲正）',
  `valid_commission_amount` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '累计有效佣金收益（等级升级口径，退款冲正）',
  `valid_customer_count` int NOT NULL DEFAULT 0 COMMENT '累计有效客户数（首次成交的直属客户）',
  `invite_count` int NOT NULL DEFAULT 0 COMMENT '累计邀请下级分销员数',
  `withdrawal_frozen` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '提现冻结金额（申请中，与 commission_frozen 分离）',
  `withdrawn_total` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '累计已提现金额（审核通过且线下打款）',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `member_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '用户ID',
  `member_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '用户名称',
  `rebate_total` decimal(10, 2) NULL DEFAULT NULL COMMENT '分销总额',
  `distribution_order_count` int NULL DEFAULT NULL COMMENT '分销订单数',
  `distribution_order_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '分销订单金额',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_distribution_invite_code`(`invite_code` ASC) USING BTREE,
  INDEX `idx_distribution_grade_id`(`grade_id` ASC) USING BTREE,
  INDEX `idx_distribution_parent`(`parent_distribution_id` ASC) USING BTREE,
  INDEX `idx_distribution_join_time`(`join_time` ASC) USING BTREE,
  INDEX `idx_distribution_member_status`(`member_id` ASC, `distribution_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '分销员' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_distribution
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_bank_card
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_bank_card`;
CREATE TABLE `li_distribution_bank_card`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `distribution_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分销员ID',
  `holder_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '收款人姓名',
  `bank_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '银行名称',
  `card_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '银行卡号',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认卡：0否 1是',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dbc_distribution`(`distribution_id` ASC) USING BTREE,
  INDEX `idx_dbc_distribution_default`(`distribution_id` ASC, `is_default` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分销员银行卡' ROW_FORMAT = DYNAMIC;

