-- Records of li_distribution_bank_card
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_cash
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_cash`;
CREATE TABLE `li_distribution_cash`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `create_by` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '创建时间',
  `delete_flag` bit(1) NULL DEFAULT NULL COMMENT '删除标志 true/false 删除/未删除',
  `update_by` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '更新时间',
  `distribution_cash_status` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '状态',
  `audit_user_id` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核人ID',
  `audit_remark` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `reject_reason` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '拒绝原因',
  `before_can_rebate` decimal(20, 2) NULL DEFAULT NULL COMMENT '申请时可提现余额快照',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `distribution_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '分销员ID',
  `distribution_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '分销员名称',
  `pay_time` datetime(6) NULL DEFAULT NULL COMMENT '支付时间',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '分销佣金',
  `sn` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '分销佣金编号',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '会员姓名',
  `id_number` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '身份证号',
  `settlement_bank_account_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '结算银行开户行名称',
  `settlement_bank_account_num` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '结算银行开户账号',
  `settlement_bank_branch_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '结算银行开户支行名称',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dc_distribution_status`(`distribution_id` ASC, `distribution_cash_status` ASC) USING BTREE,
  INDEX `idx_dc_audit_user`(`audit_user_id` ASC) USING BTREE,
  INDEX `idx_dc_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '分销佣金' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_distribution_cash
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_customer_relation
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_customer_relation`;
CREATE TABLE `li_distribution_customer_relation`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `member_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '客户会员ID',
  `distribution_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '当前直属分销员ID',
  `bind_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '绑定来源：SCAN扫码 ADMIN后台 SELF_BIND自绑定 RECRUIT招募',
  `invite_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '绑定使用的邀请码',
  `bind_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '锁客模式快照',
  `permanent_bind_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '永久锁客方式快照',
  `relation_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'UNBOUND' COMMENT '关系状态：PENDING待转永久 TEMPORARY短期 PERMANENT永久 SELF_BIND自绑定 EXPIRED已到期 UNBOUND已解绑',
  `bind_time` datetime NULL DEFAULT NULL COMMENT '绑定建立时间',
  `last_scan_time` datetime NULL DEFAULT NULL COMMENT '最近一次扫码时间',
  `pending_permanent_deadline` datetime NULL DEFAULT NULL COMMENT '待转永久截止时间',
  `expire_at` datetime NULL DEFAULT NULL COMMENT '关系到期时间（短期锁客）',
  `permanent_at` datetime NULL DEFAULT NULL COMMENT '永久生效时间',
  `trigger_order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '触发转永久的订单编号',
  `starred` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否星标客户：0否 1是',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_dcr_member`(`member_id` ASC) USING BTREE,
  INDEX `idx_dcr_distribution_status`(`distribution_id` ASC, `relation_status` ASC) USING BTREE,
  INDEX `idx_dcr_status_expire`(`relation_status` ASC, `expire_at` ASC) USING BTREE,
  INDEX `idx_dcr_bind_time`(`bind_time` ASC) USING BTREE,
  INDEX `idx_dcr_pending_deadline`(`pending_permanent_deadline` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '客户与分销员当前关系' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_distribution_customer_relation
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_customer_relation_log
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_customer_relation_log`;
CREATE TABLE `li_distribution_customer_relation_log`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `relation_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关系记录ID',
  `member_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '客户会员ID',
  `change_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '变更类型：CREATE RENEW TO_PERMANENT SELF_BIND_REPLACE EXPIRE ADMIN_REBIND ADMIN_UNBIND RETREAT',
  `before_distribution_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变更前分销员ID',
  `after_distribution_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变更后分销员ID',
  `before_relation_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变更前关系状态',
  `after_relation_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变更后关系状态',
  `before_expire_at` datetime NULL DEFAULT NULL COMMENT '变更前到期时间',
  `after_expire_at` datetime NULL DEFAULT NULL COMMENT '变更后到期时间',
  `operator_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作者ID',
  `operator_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作者类型：SYSTEM ADMIN',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变更原因',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dcrl_member_time`(`member_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_dcrl_relation_time`(`relation_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_dcrl_change_type`(`change_type` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '客户关系变更日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_distribution_customer_relation_log
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_goods
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_goods`;
CREATE TABLE `li_distribution_goods`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `create_by` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '创建时间',
  `commission` decimal(10, 2) NOT NULL COMMENT '佣金金额',
  `goods_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '商品ID',
  `goods_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '商品价格',
  `auth_status` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'PASS' COMMENT '审核状态：TOBEAUDITED待审核 PASS已审核 REFUSE审核未通过',
  `auth_remark` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `store_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '店铺ID',
  `sku_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '规格ID',
  `specs` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '规格信息json',
  `thumbnail` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '缩略图路径',
  `store_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'storeName',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '分销商品' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_distribution_goods
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_grade
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_grade`;
CREATE TABLE `li_distribution_grade`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `grade_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '等级名称',
  `grade_sort` int NOT NULL DEFAULT 0 COMMENT '等级排序（越小越低）',
  `sales_threshold` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '升级销售额阈值',
  `commission_threshold` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '升级收益额阈值',
  `invite_threshold` int NOT NULL DEFAULT 0 COMMENT '升级邀请人数阈值',
  `sales_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用销售额升级条件',
  `commission_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用收益额升级条件',
  `invite_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用邀请人数升级条件',
  `product_commission_rate` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '直属商品佣金比例（占佣金池，0.1 表示 10%）',
  `invite_commission_rate` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '邀请奖励比例（占佣金池，0.1 表示 10%）',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认等级',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志 0未删除 1已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_grade_name`(`grade_name` ASC, `delete_flag` ASC) USING BTREE,
  INDEX `idx_grade_sort`(`grade_sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分销等级配置' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_distribution_grade
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_grade_history
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_grade_history`;
CREATE TABLE `li_distribution_grade_history`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `distribution_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分销员ID',
  `previous_grade_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变更前等级值（1-5）',
  `grade_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '变更后等级值（1-5）',
  `grade_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '等级名称快照',
  `goods_commission_rate` decimal(10, 4) NULL DEFAULT NULL COMMENT '商品佣金比例快照',
  `invite_commission_rate` decimal(10, 4) NULL DEFAULT NULL COMMENT '邀请佣金比例快照',
  `upgrade_time` datetime NOT NULL COMMENT '升级时间（自动升级写入，非通用变更时间）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dgh_distribution_time`(`distribution_id` ASC, `upgrade_time` ASC) USING BTREE,
  INDEX `idx_dgh_grade`(`grade_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分销员等级变更历史' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_distribution_grade_history
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_import_batch
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_import_batch`;
CREATE TABLE `li_distribution_import_batch`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '导入文件名',
  `total_count` int NULL DEFAULT NULL COMMENT '总行数',
  `success_count` int NULL DEFAULT NULL COMMENT '成功行数',
  `fail_count` int NULL DEFAULT NULL COMMENT '失败行数',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '状态：PROCESSING/DONE/FAILED',
  `operator_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dib_status_time`(`status` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_dib_operator_time`(`operator_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分销员批量导入批次' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_distribution_import_batch
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_import_item
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_import_item`;
CREATE TABLE `li_distribution_import_item`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '批次ID',
  `row_num` int NULL DEFAULT NULL COMMENT 'Excel行号',
  `mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '手机号',
  `open_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分销员openid',
  `nickname` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '昵称',
  `inviter_mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '邀请人手机号',
  `inviter_open_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '邀请人openid',
  `grade_sort` int NULL DEFAULT NULL COMMENT '等级序号',
  `distribution_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '成功后的分销员ID',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '状态：SUCCESS/FAIL',
  `fail_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dii_batch_row`(`batch_id` ASC, `row_num` ASC) USING BTREE,
  INDEX `idx_dii_batch_status`(`batch_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_dii_distribution`(`distribution_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分销员批量导入明细' ROW_FORMAT = DYNAMIC;

