-- Records of li_distribution_import_item
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_order
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_order`;
CREATE TABLE `li_distribution_order`  (
  `id` bigint NOT NULL,
  `create_time` datetime(6) NULL DEFAULT NULL,
  `distribution_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `distribution_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `invite_distribution_id` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '二级分销员ID（邀请奖励受益人）',
  `invite_distribution_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '二级分销员名称',
  `performance_distributor_id` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '业绩归属分销员ID（统计口径唯一归属）',
  `self_purchase` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否分销员自购：0否 1是',
  `payment_time` datetime NULL DEFAULT NULL COMMENT '支付成功时间',
  `commission_pool` decimal(20, 2) NULL DEFAULT NULL COMMENT '本明细佣金池金额（固定佣金×数量）',
  `relation_snapshot` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '支付时客户关系快照（JSON）',
  `pay_snapshot` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '支付时商品佣金/等级/结算配置快照（JSON）',
  `distribution_order_status` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `goods_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `goods_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `image` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `member_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `member_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `num` int NULL DEFAULT NULL,
  `order_item_sn` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `order_sn` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `rebate` decimal(10, 2) NULL DEFAULT NULL,
  `invite_commission` double NULL DEFAULT NULL COMMENT '二级邀请佣金',
  `sell_back_rebate` decimal(10, 2) NULL DEFAULT NULL,
  `invite_sell_back_rebate` double NULL DEFAULT 0 COMMENT '二级邀请佣金退款冲回金额',
  `settle_cycle` datetime(6) NULL DEFAULT NULL,
  `settle_time` datetime NULL DEFAULT NULL COMMENT '佣金结算时间',
  `sku_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `specs` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `store_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `store_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `refund_num` int NULL DEFAULT NULL COMMENT '退款商品数量',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_do_order_item_sn`(`order_item_sn` ASC) USING BTREE,
  INDEX `idx_do_performance_distributor`(`performance_distributor_id` ASC) USING BTREE,
  INDEX `idx_do_payment_time`(`payment_time` ASC) USING BTREE,
  INDEX `idx_do_perf_payment`(`performance_distributor_id` ASC, `payment_time` ASC) USING BTREE,
  INDEX `idx_do_member_payment`(`member_id` ASC, `payment_time` ASC) USING BTREE,
  INDEX `idx_do_order_sn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '分销订单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_distribution_order
-- ----------------------------

-- ----------------------------
-- Table structure for li_distribution_recruit_application
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_recruit_application`;
CREATE TABLE `li_distribution_recruit_application`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `member_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请人会员ID',
  `plan_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分销招募设置ID（li_setting）',
  `plan_version_no` int NOT NULL COMMENT '申请时设置版本号',
  `apply_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请来源：MANUAL_ENTRY AUTO_ENTRY ADMIN',
  `condition_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '条件快照（JSON）',
  `apply_form_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '动态填写内容快照（JSON）',
  `recruit_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '招募邀请令牌',
  `recruit_inviter_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '招募邀请方分销员ID',
  `bound_distributor_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请时客户绑定分销员ID',
  `agreement_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '申请时服务协议内容快照（富文本）',
  `agreement_accept_time` datetime NULL DEFAULT NULL COMMENT '协议接受时间',
  `audit_mode_snapshot` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审核方式快照',
  `application_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态：PENDING待审核 APPROVED已通过 REJECTED已拒绝 CANCELLED已取消',
  `audit_user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审核人ID',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '拒绝原因',
  `distribution_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审核通过后关联的分销员ID',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dra_member_status`(`member_id` ASC, `application_status` ASC) USING BTREE,
  INDEX `idx_dra_plan_time`(`plan_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_dra_status_time`(`application_status` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_dra_recruit_inviter`(`recruit_inviter_id` ASC) USING BTREE,
  INDEX `idx_dra_distribution`(`distribution_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分销员招募申请记录' ROW_FORMAT = DYNAMIC;

