  `sku_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'SKU ID',
  `channel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分享渠道：WECHAT_MINI_PROGRAM H5 等',
  `trigger_page` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '触发页面：distribution_home distribution_share 等',
  `share_button_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分享按钮类型：IMMEDIATE_SHARE SAVE_TEXT_IMAGE SAVE_POSTER 等',
  `share_time` datetime NOT NULL COMMENT '分享点击时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_dse_event_id`(`event_id` ASC) USING BTREE,
  INDEX `idx_dse_share_id`(`share_id` ASC) USING BTREE,
  INDEX `idx_dse_distribution_time`(`distribution_id` ASC, `share_time` ASC) USING BTREE,
  INDEX `idx_dse_goods_time`(`goods_id` ASC, `share_time` ASC) USING BTREE,
  INDEX `idx_dse_share_time`(`share_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分销商品分享行为记录' ROW_FORMAT = DYNAMIC;

