  INDEX `idx_dve_visitor_time`(`visitor_id` ASC, `visit_time` ASC) USING BTREE,
  INDEX `idx_dve_member_time`(`member_id` ASC, `visit_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分销分享链接访问记录' ROW_FORMAT = DYNAMIC;

