-- ----------------------------
-- Table structure for li_distribution_wallet_log
-- ----------------------------
DROP TABLE IF EXISTS `li_distribution_wallet_log`;
CREATE TABLE `li_distribution_wallet_log`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键',
  `distribution_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分销员ID',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务类型：COMMISSION_FREEZE COMMISSION_SETTLE COMMISSION_REFUND WITHDRAW_APPLY WITHDRAW_APPROVE WITHDRAW_REJECT MANUAL_ADJUST',
  `biz_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务单号（订单号/提现单号等）',
  `change_amount` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '本次变动金额（可正可负）',
  `before_can_rebate` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前可提现余额',
  `after_can_rebate` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后可提现余额',
  `before_commission_frozen` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前待结算佣金冻结',
  `after_commission_frozen` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后待结算佣金冻结',
  `before_withdrawal_frozen` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前提现冻结',
  `after_withdrawal_frozen` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后提现冻结',
  `before_withdrawn_total` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前累计已提现',
  `after_withdrawn_total` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后累计已提现',
  `operator_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作者ID',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `idempotent_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '幂等键（全局唯一）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_dwl_idempotent`(`idempotent_key` ASC) USING BTREE,
  INDEX `idx_dwl_distribution_time`(`distribution_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_dwl_biz`(`biz_type` ASC, `biz_sn` ASC) USING BTREE,
  INDEX `idx_dwl_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分销钱包流水' ROW_FORMAT = DYNAMIC;

