-- ----------------------------
-- Table structure for li_gift_card_cash_activity
-- ----------------------------
DROP TABLE IF EXISTS `li_gift_card_cash_activity`;
CREATE TABLE `li_gift_card_cash_activity`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL,
  `create_time` datetime(6) NULL DEFAULT NULL,
  `delete_flag` bit(1) NULL DEFAULT b'0',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL,
  `update_time` datetime(6) NULL DEFAULT NULL,
  `gift_card_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '活动名称/礼品卡名称',
  `card_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'CASH' COMMENT 'CASH/PICKUP(本期未实现)',
  `face_value` decimal(12, 2) NOT NULL COMMENT '单卡面额',
  `validity_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'LONG_TERM',
  `valid_end_time` datetime(6) NULL DEFAULT NULL,
  `valid_months_after_activate` int NULL DEFAULT NULL,
  `stock_total` int NOT NULL COMMENT '活动库存：最多可制凭证张数',
  `pickup_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'ONE任选一、ALL全选、ANY任选N种',
  `pickup_count` int NULL DEFAULT NULL COMMENT '单次兑换SKU种数，每种一件',
  `pickup_sku_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '可兑换SKU ID的JSON快照，制发卡后不可变',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_li_gift_card_cash_activity_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '现金礼品卡活动' ROW_FORMAT = DYNAMIC;

