  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_li_gift_card_cash_create_batch_activity`(`activity_id` ASC) USING BTREE,
  INDEX `idx_li_gift_card_cash_create_batch_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '现金礼品卡制卡批次' ROW_FORMAT = DYNAMIC;

