-- ----------------------------
-- Table structure for li_gift_card_cash_credential
-- ----------------------------
DROP TABLE IF EXISTS `li_gift_card_cash_credential`;
CREATE TABLE `li_gift_card_cash_credential`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL,
  `create_time` datetime(6) NULL DEFAULT NULL,
  `delete_flag` bit(1) NULL DEFAULT b'0',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL,
  `update_time` datetime(6) NULL DEFAULT NULL,
  `activity_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `create_batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '制卡批次ID（制卡写入；导入发卡可为空）',
  `issue_batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL,
  `member_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发卡后会员ID',
  `bind_time` datetime(6) NULL DEFAULT NULL COMMENT '绑定时间（用户与卡绑定时写入）',
  `activate_member_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '激活会员ID',
  `activate_time` datetime(6) NULL DEFAULT NULL COMMENT '激活时间（激活后方可使用）',
  `expire_time` datetime(6) NULL DEFAULT NULL COMMENT '卡到期时间（按活动有效期规则计算）',
  `card_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `card_secret` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `face_value` decimal(12, 2) NOT NULL COMMENT '单卡面额',
  `balance` decimal(12, 2) NULL DEFAULT NULL COMMENT '当前余额（发卡后初始化为面额）',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'UNISSUED/BOUND/VOIDED/EXPIRED',
  `card_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'CASH' COMMENT 'CASH现金卡、PICKUP提货卡快照',
  `pickup_trade_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '成功兑换交易号，取消不清空',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_li_gift_card_cash_credential_card_no`(`card_no` ASC) USING BTREE,
  INDEX `idx_li_gift_card_cash_cred_activity_status`(`activity_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_li_gift_card_cash_cred_batch_status`(`create_batch_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_li_gift_card_cash_cred_issue`(`issue_batch_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '现金礼品卡卡密凭证' ROW_FORMAT = DYNAMIC;

