  `auth_flag` bit(1) NULL DEFAULT NULL COMMENT '审核标识 是否审核评论',
  `live_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '直播状态',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '直播编号',
