-- ----------------------------
-- Table structure for li_order_gift_card_record
-- ----------------------------
DROP TABLE IF EXISTS `li_order_gift_card_record`;
CREATE TABLE `li_order_gift_card_record`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL,
  `create_time` datetime(6) NULL DEFAULT NULL,
  `delete_flag` bit(1) NULL DEFAULT b'0',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL,
  `update_time` datetime(6) NULL DEFAULT NULL,
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '订单号',
  `trade_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '交易号',
  `member_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '会员ID',
  `credential_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '礼品卡凭证ID',
  `card_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '礼品卡卡号',
  `deduct_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '本次抵扣金额（兼容历史字段）',
  `change_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '变动金额（正数增加，负数减少）',
  `balance_after` decimal(12, 2) NULL DEFAULT NULL COMMENT '变动后余额',
  `flow_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '流水方向：INCREASE/DECREASE',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '业务类型：ORDER_DEDUCT/ORDER_REFUND/CARD_ACTIVATE',
  `biz_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '业务单号（售后单号/订单号等）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_li_order_gift_card_record_order`(`order_sn` ASC) USING BTREE,
  INDEX `idx_li_order_gift_card_record_trade`(`trade_sn` ASC) USING BTREE,
  INDEX `idx_li_order_gift_card_record_member`(`member_id` ASC) USING BTREE,
  INDEX `idx_li_order_gift_card_record_credential`(`credential_id` ASC) USING BTREE,
  INDEX `idx_li_order_gift_card_record_biz`(`biz_type` ASC, `biz_sn` ASC) USING BTREE,
  INDEX `idx_pickup_order_flow`(`order_sn` ASC, `biz_type` ASC, `delete_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '礼品卡使用记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_order_gift_card_record
-- ----------------------------

-- ----------------------------
-- Table structure for li_order_item
-- ----------------------------
DROP TABLE IF EXISTS `li_order_item`;
CREATE TABLE `li_order_item`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `create_by` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '创建时间',
  `delete_flag` bit(1) NULL DEFAULT NULL COMMENT '删除标志 true/false 删除/未删除',
  `update_by` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '更新时间',
  `after_sale_status` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '售后状态',
  `category_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '分类ID',
  `comment_status` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '评论状态',
  `complain_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '交易投诉ID',
  `complain_status` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '投诉状态',
  `flow_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '实际金额',
  `goods_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '销售金额',
  `goods_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '商品ID',
  `image` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '图片',
  `goods_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `num` int NULL DEFAULT NULL COMMENT '销售量',
  `order_sn` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '订单编号',
  `price_detail` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '价格详情',
  `promotion_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '促销ID',
  `promotion_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '促销类型',
  `sku_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '货品ID',
  `sn` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '子订单编号',
  `snapshot_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '快照ID',
  `specs` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '规格json',
  `trade_sn` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '交易编号',
  `price_fluctuation_ratio` decimal(10, 2) NULL DEFAULT NULL COMMENT '浮动价格比例',
  `unit_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '单价',
  `sub_total` decimal(10, 2) NULL DEFAULT NULL COMMENT '小记',
  `return_goods_number` int NULL DEFAULT 0 COMMENT '已退货数量 ',
  `is_goods_number` int NULL DEFAULT 0 COMMENT '正在进行售后的商品数量 ',
  `deliver_number` int NULL DEFAULT NULL COMMENT '发货数量',
  `is_refund` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '是否退款',
  `refund_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '退款金额',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_item_order_sn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '子订单' ROW_FORMAT = DYNAMIC;

