  INDEX `idx_li_procurement_inbound_store_id`(`store_id` ASC) USING BTREE,
  INDEX `idx_li_procurement_inbound_order_id`(`procurement_order_id` ASC) USING BTREE,
  INDEX `idx_li_procurement_inbound_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '采购入库单' ROW_FORMAT = DYNAMIC;

