CREATE TABLE `li_procurement_order_item`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '创建时间',
  `procurement_order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '采购订单ID',
  `goods_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '商品ID',
  `sku_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'SKU ID',
  `goods_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '商品名称',
  `retail_price` decimal(20, 2) NULL DEFAULT NULL COMMENT '零售价',
  `quantity` int NULL DEFAULT NULL COMMENT '采购数量',
  `tax_rate` int NULL DEFAULT NULL COMMENT '税率(百分比整数)',
