  `unit_price_without_tax` decimal(20, 2) NULL DEFAULT NULL COMMENT '不含税单价',
  `subtotal_without_tax` decimal(20, 2) NULL DEFAULT NULL COMMENT '不含税小计',
  `subtotal_with_tax` decimal(20, 2) NULL DEFAULT NULL COMMENT '含税小计',
  `received_quantity` int NULL DEFAULT NULL COMMENT '已入库数量',
