-- Table structure for li_store_flow
-- ----------------------------
DROP TABLE IF EXISTS `li_store_flow`;
CREATE TABLE `li_store_flow`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一标识',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '流水编号',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '订单sn',
  `order_item_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '子订单sn',
  `refund_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '售后SN',
  `store_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '店铺id',
  `store_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '店铺名称',
  `member_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户id',
  `member_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户名称',
  `goods_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品ID',
  `goods_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品名称',
  `sku_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '货品ID',
  `image` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图片',
  `category_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类ID',
  `specs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '规格json',
  `flow_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '流水类型：PAY/REFUND 支付/退款',
  `order_promotion_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '订单促销类型',
  `point_settlement_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '积分活动商品结算价格',
  `kanjia_settlement_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '砍价活动商品结算价格',
  `flash_discount_subsidy` decimal(10, 2) NULL DEFAULT NULL COMMENT '限时直降补贴',
  `nth_item_subsidy` decimal(10, 2) NULL DEFAULT NULL COMMENT '第N件优惠补贴',
  `site_coupon_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '平台优惠券使用金额',
  `site_coupon_point` decimal(10, 2) NULL DEFAULT NULL COMMENT '站点优惠券补贴比例',
  `site_coupon_commission` decimal(10, 2) NULL DEFAULT NULL COMMENT '站点优惠券补贴金额',
  `gift_card_subsidy_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '礼品卡平台补贴金额（抵扣金额，由平台承担）',
  `distribution_rebate` decimal(10, 2) NULL DEFAULT NULL COMMENT '单品分销返现支出',
  `commission_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '平台收取交易佣金',
  `final_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '流水金额（用户实际支付现金，已扣礼品卡）',
  `settlement_base_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '商家结算计费基数（有礼品卡时=final_price+gift_card_subsidy_price）',
  `bill_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '最终结算金额（商家入账）',
  `transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '第三方交易流水号',
  `payment_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支付方式名称',
  `num` int NULL DEFAULT NULL COMMENT '销售量',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `bill_time` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `full_refund` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否全部退款，1为全部退款',
  `profit_sharing_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分账状态',
  `profit_sharing` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '实际分账金额DTO',
  `paid_member_subsidy_price` decimal(18, 2) NOT NULL DEFAULT 0.00,
  `paid_member_order_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sn`(`sn` ASC) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_store_id`(`store_id` ASC) USING BTREE,
  INDEX `idx_bill_time`(`bill_time` ASC) USING BTREE,
  INDEX `idx_flow_paid_member_order`(`paid_member_order_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商家订单流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of li_store_flow
