-- Table structure for li_system_log
-- ----------------------------
DROP TABLE IF EXISTS `li_system_log`;
CREATE TABLE `li_system_log`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主键',
  `create_time` bigint NULL DEFAULT NULL COMMENT '日志记录时间',
  `username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '请求用户',
  `request_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '请求路径',
  `request_param` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '请求参数',
  `response_body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '响应参数',
  `ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'ip',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '方法操作名称',
  `request_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '请求类型',
  `customer_log` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '自定义日志内容',
  `ip_info` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'ip信息',
  `cost_time` int NULL DEFAULT NULL COMMENT '花费时间',
  `store_id` bigint NULL DEFAULT NULL COMMENT '商家',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_li_system_log_store_id`(`store_id` ASC) USING BTREE,
  INDEX `idx_li_system_log_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统操作日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_system_log
-- ----------------------------

-- ----------------------------
-- Table structure for li_timed_task
-- ----------------------------
DROP TABLE IF EXISTS `li_timed_task`;
CREATE TABLE `li_timed_task`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务唯一标识',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务名称',
  `group_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '默认任务' COMMENT '任务分组',
  `bean_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Spring Bean类名或名称',
  `method_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'execute' COMMENT '调用的方法名',
  `cron` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Cron 表达式',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1 启用，0 停用',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务描述',
  `last_exec_time` datetime NULL DEFAULT NULL COMMENT '上次执行时间',
  `last_exec_status` tinyint(1) NULL DEFAULT NULL COMMENT '上次执行结果：1 成功，0 失败',
  `last_exec_cost` bigint NULL DEFAULT NULL COMMENT '上次执行耗时(毫秒)',
  `last_exec_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '上次执行异常信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '定时任务配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of li_timed_task
-- ----------------------------

